"""Application icon: a relay whose linkage is the Morse letter K (generated by packaging/make_icon.py)."""
from __future__ import annotations

import sys

from PySide6.QtGui import QIcon

from ..core.resources import resource_path

SIZES = (16, 20, 24, 32, 48, 64, 128, 256, 512)


def app_icon() -> QIcon:
    """All PNG sizes in one QIcon, so Qt picks the hand-tuned small drawing for title bars and taskbars."""
    folder = resource_path("cwstation/assets")
    icon = QIcon()
    for size in SIZES:
        path = folder / f"icon-{size}.png"
        if path.exists():
            icon.addFile(str(path))
    return icon


def set_windows_app_id(app_id: str = "CWStation.CWStation") -> None:
    """Give the process its own taskbar identity on Windows; without it a source run shows python.exe's icon."""
    if sys.platform != "win32":
        return
    try:
        import ctypes

        ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(app_id)
    except Exception:  # noqa: BLE001 - cosmetic only
        pass
